119	bool
120	TestStream::StartPing(
121	    _In_ uint64_t PayloadLength
122	    )
123	{
124	    BytesToSend = PayloadLength / MaxSendBuffers;
125	
126	    do {
127	        auto SendBufferLength = (uint32_t)CXPLAT_MIN(BytesToSend, (int64_t)MaxSendLength);
128	        auto SendBuffer = new(std::nothrow) QuicSendBuffer(MaxSendBuffers, SendBufferLength);
129	        if (SendBuffer == nullptr) {
130	            TEST_FAILURE("Failed to alloc QuicSendBuffer");
131	            return false;
132	        }
133	
134	        auto resultingBytesLeft = InterlockedSubtract64(&BytesToSend, SendBufferLength);
135	
136	        QUIC_SEND_FLAGS Flags = QUIC_SEND_FLAG_ALLOW_0_RTT;
137	        if (PayloadLength == 0) {
138	            Flags |= QUIC_SEND_FLAG_START;
139	        }
140	        if (resultingBytesLeft == 0) {
141	            Flags |= QUIC_SEND_FLAG_FIN;
142	        }
143	
144	        InterlockedIncrement(&OutstandingSendRequestCount);
145	        QUIC_STATUS Status =
146	            MsQuic->StreamSend(
147	                QuicStream,
148	                SendBuffer->Buffers,
149	                SendBuffer->BufferCount,
150	                Flags,
151	                SendBuffer);
152	        if (QUIC_FAILED(Status)) {
153	            InterlockedDecrement(&OutstandingSendRequestCount);
154	            delete SendBuffer;
155	            TEST_FAILURE("MsQuic->StreamSend failed, 0x%x.", Status);
156	            return false;
157	        }
158	        if (resultingBytesLeft == 0) {
159	            // On the finish packet if it succeeds, the instance
160	            // we are executing in will be deleted. Return
161	            // so we don't execute the while on a deleted instance.
162	            return true;
163	        }
164	
165	    } while (BytesToSend != 0 && OutstandingSendRequestCount < (int64_t)MaxSendRequestQueue);
166	
167	    return true;
168	}
